// ── src/lib/meta.js ──
// WhatsApp Cloud API webhook parsing.
//
// Inlined into n8n Code nodes by scripts/build-workflows.mjs, so this file must stay
// dependency-free and only declare functions/constants.

const PHONE_ID_PATTERN = /^\d{6,15}$/;
// Business-scoped user ID: ISO country code, a dot, then an opaque ID (e.g. "GH.13491208655302741918").
const BSUID_PATTERN = /^[A-Z]{2}\.[A-Za-z0-9._-]{1,160}$/;

function metaIdentity(message, contact) {
  const m = message || {};
  const c = contact || {};
  const idCandidates = [m.from, c.wa_id].filter(Boolean).map(String);
  const phone = idCandidates.find((v) => PHONE_ID_PATTERN.test(v)) || null;
  const explicitBsuid = [m.from_user_id, m.user_id, c.user_id].filter(Boolean).map(String)[0];
  const bsuid = explicitBsuid || idCandidates.find((v) => BSUID_PATTERN.test(v)) || null;
  return {
    phone,
    bsuid,
    profileName: (c.profile && c.profile.name) || null,
    username: c.username || (c.profile && c.profile.username) || null,
  };
}

function metaMedia(part) {
  if (!part) return null;
  return {
    mediaId: part.id || null,
    mimeType: part.mime_type || null,
    sha256: part.sha256 || null,
    caption: part.caption || null,
    filename: part.filename || null,
    voice: part.voice === true,
  };
}

// Reduces one inbound message to the fields the workflows use, plus a one-line `body` for the log.
function metaMessage(m, contact, metadata) {
  const type = m.type || 'unknown';
  const out = {
    kind: 'message',
    waMessageId: m.id,
    timestamp: m.timestamp ? Number(m.timestamp) : null,
    phoneNumberId: (metadata && metadata.phone_number_id) || null,
    from: metaIdentity(m, contact),
    type,
    text: null,
    media: null,
    location: null,
    reply: null,
    reaction: null,
    contextId: (m.context && m.context.id) || null,
    referral: m.referral || null,
    errors: m.errors || null,
    body: null,
  };

  switch (type) {
    case 'text':
      out.text = (m.text && m.text.body) || '';
      out.body = out.text;
      break;
    case 'image':
    case 'video':
    case 'audio':
    case 'document':
    case 'sticker':
      out.media = metaMedia(m[type]);
      out.text = (out.media && out.media.caption) || null;
      out.body = `[${type === 'audio' && out.media && out.media.voice ? 'voice note' : type}]` +
        (out.text ? ` ${out.text}` : '');
      break;
    case 'location': {
      const l = m.location || {};
      out.location = {
        latitude: Number(l.latitude),
        longitude: Number(l.longitude),
        name: l.name || null,
        address: l.address || null,
        url: l.url || null,
      };
      out.body = `[location] ${[l.name, l.address].filter(Boolean).join(', ') || `${l.latitude},${l.longitude}`}`;
      break;
    }
    case 'interactive': {
      const i = m.interactive || {};
      const r = i.button_reply || i.list_reply || null;
      if (r) {
        out.reply = { id: r.id || '', title: r.title || '', description: r.description || null };
        out.body = `[reply] ${out.reply.title}`;
      } else if (i.nfm_reply) {
        out.reply = { id: 'flow', title: i.nfm_reply.name || 'flow', responseJson: i.nfm_reply.response_json || null };
        out.body = '[flow reply]';
      }
      break;
    }
    case 'button':
      // quick-reply button on a template message
      out.reply = { id: (m.button && m.button.payload) || '', title: (m.button && m.button.text) || '' };
      out.body = `[reply] ${out.reply.title}`;
      break;
    case 'reaction':
      out.reaction = { messageId: (m.reaction && m.reaction.message_id) || null, emoji: (m.reaction && m.reaction.emoji) || '' };
      out.body = `[reaction] ${out.reaction.emoji}`;
      break;
    default:
      out.body = `[${type}]`;
  }
  return out;
}

function metaStatus(s, metadata) {
  return {
    kind: 'status',
    waMessageId: s.id,
    status: s.status,
    timestamp: s.timestamp ? Number(s.timestamp) : null,
    phoneNumberId: (metadata && metadata.phone_number_id) || null,
    recipientPhone: s.recipient_id || null,
    recipientBsuid: s.recipient_user_id || null,
    errors: s.errors || null,
  };
}

// One webhook POST can batch several messages and statuses; returns them as a flat list.
function normalizeWebhook(body) {
  const events = [];
  if (!body || body.object !== 'whatsapp_business_account' || !Array.isArray(body.entry)) return events;
  for (const entry of body.entry) {
    for (const change of entry.changes || []) {
      if (change.field !== 'messages' || !change.value) continue;
      const v = change.value;
      const contacts = Array.isArray(v.contacts) ? v.contacts : [];
      for (const m of v.messages || []) {
        const contact =
          contacts.find((c) => (m.from && c.wa_id === m.from) || (m.from_user_id && c.user_id === m.from_user_id)) ||
          contacts[0] ||
          {};
        events.push(metaMessage(m, contact, v.metadata));
      }
      for (const s of v.statuses || []) events.push(metaStatus(s, v.metadata));
    }
  }
  return events;
}

// ── node logic ──
const body = $('Webhook').first().json.body;
const settings = $('Settings').first().json.settings;
const ourNumber = settings.whatsapp && settings.whatsapp.phone_number_id;
return normalizeWebhook(body)
  // ignore events for other numbers on the same WhatsApp Business Account
  .filter((e) => !ourNumber || !e.phoneNumberId || String(e.phoneNumberId) === String(ourNumber))
  .map((event) => ({ json: { event } }));

// ── src/lib/orders.js ──
// Storefront order contract (see Whatsapp-storefront/docs/whatsapp-bot-contract.md):
//
//   Order: {Variant} {Size} x{Qty}
//   Name: {Customer name}
//
// Inlined into n8n Code nodes; keep dependency-free.

// Reference patterns exported by the storefront (lib/whatsapp.ts). The parser below accepts a
// superset (any case, "×" for x, stray spaces) because customers sometimes edit the text.
const ORDER_LINE_PATTERN = /^Order: (.+) (\d+)ml x(\d+)$/m;
const NAME_LINE_PATTERN = /^Name: ([\p{L}\p{M}' .-]{2,40})$/mu;

const LENIENT_ORDER_LINE = /^[ \t]*order[ \t]*:[ \t]*(.+?)[ \t]+(\d{2,4})[ \t]*ml[ \t]*[x×*][ \t]*(\d{1,3})[ \t]*$/im;
const LENIENT_NAME_LINE = /^[ \t]*name[ \t]*:[ \t]*(.+?)[ \t]*$/im;
const ORDER_ATTEMPT = /^[ \t]*order[ \t]*:/im;

const NAME_MAX = 40;

// Same cleaning as the storefront's sanitizeName: letters, marks, spaces, apostrophes, dots and
// hyphens on one line, so a name can't smuggle in a second "Order:" line.
function sanitizeName(raw) {
  return String(raw == null ? '' : raw)
    .normalize('NFKC')
    .replace(/[^\p{L}\p{M}' .-]/gu, ' ')
    .replace(/\s+/g, ' ')
    .trim()
    .slice(0, NAME_MAX);
}

// Returns {variant, size, qty, name} or null. Validation against the catalog happens in the
// database (crm.create_order), which is the single pricing authority.
function parseOrderMessage(text) {
  if (typeof text !== 'string') return null;
  const t = text.replace(/\r\n?/g, '\n');
  const m = t.match(LENIENT_ORDER_LINE);
  if (!m) return null;
  const n = t.match(LENIENT_NAME_LINE);
  const name = n ? sanitizeName(n[1]) : '';
  return {
    variant: m[1].replace(/\s+/g, ' ').trim(),
    size: `${Number(m[2])}ml`,
    qty: Number(m[3]),
    name: name.length >= 2 ? name : null,
  };
}

// "Order:" is there but the line doesn't parse: worth a format hint rather than the AI agent.
function looksLikeOrderAttempt(text) {
  return typeof text === 'string' && ORDER_ATTEMPT.test(text) && parseOrderMessage(text) === null;
}

function money(amount, currency) {
  return `${currency || 'GHS'} ${Number(amount || 0).toFixed(2)}`;
}

function orderLines(order) {
  const currency = (order && order.currency) || 'GHS';
  return ((order && order.items) || []).map(
    (i) => `${i.qty} × ${i.variant} ${i.size} — ${money(Number(i.unit_price) * Number(i.qty), currency)}`,
  );
}

function itemsSummary(order) {
  return ((order && order.items) || []).map((i) => `${i.qty} × ${i.variant} ${i.size}`).join(', ');
}

// ── src/lib/router.js ──
// Decides what happens to each inbound message. Deterministic paths (orders, payments, delivery
// pins, keywords, owner actions) never reach the AI agent: they're cheaper, faster and can't be
// talked into doing something else.
//
// Inlined into n8n Code nodes after orders.js (uses parseOrderMessage / looksLikeOrderAttempt).
/* global parseOrderMessage, looksLikeOrderAttempt */

const ROUTE_KEYWORDS = {
  optOut: /^\s*(stop|stop all|unsubscribe)\s*[.!]*\s*$/i,
  optIn: /^\s*(start|unstop|subscribe)\s*[.!]*\s*$/i,
  human: /^\s*(human|agent|person|real person|(talk|speak|chat) (to|with) (a |the )?(human|person|someone|agent|team|owner)|call me)\s*[.!?]*\s*$/i,
  cancel: /^\s*cancel( (my|the))?( order)?\s*[.!]*\s*$/i,
};

function describeLocation(location) {
  const l = location || {};
  return [l.name, l.address].filter(Boolean).join(', ') || `${l.latitude}, ${l.longitude}`;
}

// msg: output of metaMessage(); state: output of crm.ingest_inbound().
// Returns {route, ...details}.
function routeInbound(msg, state) {
  if (!state || state.duplicate) return { route: 'ignore', reason: 'duplicate' };
  const customer = state.customer || {};
  if (customer.is_owner) return { route: 'owner' };

  const text = String(msg.text || '').trim();
  const replyId = (msg.reply && msg.reply.id) || '';

  if (['reaction', 'sticker', 'system', 'request_welcome'].includes(msg.type)) {
    return { route: 'ignore', reason: msg.type };
  }

  // A checkout message or a payment screenshot still goes through the normal flow while the
  // owner is chatting with this customer; everything else is forwarded to the owner.
  const order = msg.type === 'text' ? parseOrderMessage(text) : null;
  if (customer.bot_paused) {
    if (order) return { route: 'order', order };
    if (msg.type === 'image' && state.open_order) return { route: 'payment' };
    return { route: 'takeover_forward' };
  }

  if (replyId.startsWith('cust:')) {
    const [, action, id] = replyId.split(':');
    if (action === 'cancel') return { route: 'cancel', orderId: Number(id) || null };
    if (action === 'human') return { route: 'human', reason: 'Tapped "Talk to a person"' };
  }

  switch (msg.type) {
    case 'text':
      if (ROUTE_KEYWORDS.optOut.test(text)) return { route: 'opt_out' };
      if (ROUTE_KEYWORDS.optIn.test(text)) return { route: 'opt_in' };
      if (ROUTE_KEYWORDS.human.test(text)) return { route: 'human', reason: 'Asked for a person' };
      if (ROUTE_KEYWORDS.cancel.test(text)) return { route: 'cancel', orderId: null };
      if (order) return { route: 'order', order };
      if (looksLikeOrderAttempt(text)) return { route: 'order_help' };
      return { route: 'agent' };
    case 'image':
      if (state.open_order) return { route: 'payment' };
      return { route: 'agent', note: `[The customer sent a photo${text ? ` with the caption "${text}"` : ''}]` };
    case 'document':
      return state.open_order ? { route: 'receipt_not_image' } : { route: 'unsupported' };
    case 'location':
      if (state.awaiting_location_order) return { route: 'location' };
      return { route: 'agent', note: `[The customer shared a location: ${describeLocation(msg.location)}]` };
    case 'audio':
      return { route: 'voice' };
    case 'interactive':
    case 'button':
      // an old button, or a button from a message the bot didn't send
      return { route: 'agent', note: `[The customer tapped "${(msg.reply && msg.reply.title) || 'a button'}"]` };
    case 'video':
    case 'contacts':
    case 'order':
    case 'unsupported':
      return { route: 'unsupported' };
    default:
      return { route: 'ignore', reason: msg.type };
  }
}

// ── node logic ──
const settings = $('Settings').first().json.settings;
const out = [];
for (const item of $input.all()) {
  const { state, event } = item.json;
  const decision = routeInbound(event, state);
  if (decision.route === 'ignore') continue;
  out.push({ json: { route: decision.route, decision, msg: event, state, settings } });
}
return out;
